update public.user_patrols p set hometown_bonus_snapshot=p.hometown_bonus_snapshot||jsonb_build_object('cash',floor(q.progression_cash_reward::numeric*coalesce((p.hometown_bonus_snapshot->>'cash_bonus_rate')::numeric,0))::bigint,'progression_base_cash',q.progression_cash_reward) from public.canonical_quest_master q where q.version='2026-08-30' and q.quest_id=coalesce(p.course_id,p.quest_id) and p.progression_kind in('FIRST_CLEAR','REPEAT') and p.status in('ONGOING','CLAIMABLE') and p.exploration_reward_receipt is null;
commit;
